local message = Instance.new("Message")
message.Parent = workspace

workspace:SetPhysicsThrottleEnabled(true)

-- This code might move to C++
function characterRessurection(player)
if player.Character then
local humanoid = player.Character.Humanoid
humanoid.Died:connect(function() wait(5) player:LoadCharacter() end)
end
end
game:GetService("Players").PlayerAdded:connect(function(player)
characterRessurection(player)
player.Changed:connect(function(name)
if name=="Character" then
characterRessurection(player)
end
end)
end)

function doVisit()
message.Text = "Loading Game"
if true then
game:Load("http://www.roblox.com/asset/?id=2648025")
visit:SetUploadUrl("http://www.roblox.com/Data/Upload.ashx?assetid=2648025")
end

message.Text = "Running"
game:GetService("RunService"):Run()

message.Text = "Creating Player"
if true then
player = game:GetService("Players"):CreateLocalPlayer(582128)
player.Name = [====[jrf2112]====]
else
player = game:GetService("Players"):CreateLocalPlayer(0)
end
player.CharacterAppearance = "http://www.roblox.com/Asset/CharacterFetch.ashx?userId=582128&placeId=2648025"
player:LoadCharacter()